def append_once(path, record):
    """Append a finite JSON record once; all writers must use this lock."""
    import fcntl
    import json
    import math
    import os

    def validate(value):
        if value is None or isinstance(value, (str, bool, int)):
            return
        if isinstance(value, float):
            if not math.isfinite(value):
                raise ValueError("Nonfinite JSON number")
            return
        if isinstance(value, list):
            for item in value:
                validate(item)
            return
        if isinstance(value, dict):
            for key, item in value.items():
                if not isinstance(key, str):
                    raise ValueError("JSON keys must be strings")
                validate(item)
            return
        raise ValueError("Not a JSON value")

    def validate_record(value):
        if not isinstance(value, dict):
            raise ValueError("Record must be a JSON dict")
        if not isinstance(value.get("id"), str) or not value["id"]:
            raise ValueError("Record needs a nonempty string id")
        validate(value)

    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError("Duplicate JSON object key")
            result[key] = value
        return result

    def reject_constant(value):
        raise ValueError("Nonfinite JSON number: " + value)

    def encode(value):
        return json.dumps(value, allow_nan=False, sort_keys=True,
                          separators=(",", ":"), ensure_ascii=True).encode("ascii")

    # Finish validation/serialization before even opening the ledger.
    validate_record(record)
    encoded = encode(record)
    record_id = record["id"]
    fd = os.open(path, os.O_RDWR | os.O_CREAT | os.O_APPEND, 0o600)
    try:
        handle = os.fdopen(fd, "r+b")
    except BaseException:
        os.close(fd)
        raise
    with handle:
        fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
        seen = set()
        found = None
        needs_separator = False
        handle.seek(0)
        for line in handle:
            try:
                existing = json.loads(line.decode("utf-8"),
                                      object_pairs_hook=pairs,
                                      parse_constant=reject_constant)
                validate_record(existing)
            except (ValueError, TypeError, RecursionError) as exc:
                raise ValueError("Malformed ledger row") from exc
            identifier = existing["id"]
            if identifier in seen:
                raise ValueError("Duplicate ledger id")
            seen.add(identifier)
            if identifier == record_id:
                found = encode(existing)
            needs_separator = not line.endswith(b"\n")
        if found is not None:
            if found != encoded:
                raise ValueError("Existing id has changed content")
            return False
        handle.seek(0, os.SEEK_END)
        handle.write((b"\n" if needs_separator else b"") + encoded + b"\n")
        handle.flush()
        os.fsync(handle.fileno())
        return True
